import React from 'react';
// Painted placeholders live in public/art/<kind>.png (generated by tools/paint.py).
// Swap any file for a real DPX photo and nothing else changes.
export default function Scene({ kind = 'hero', className = '' }) {
  const hero = kind === 'hero';
  return <img className={`scene ${className}`} src={`./art/${kind}.png`} width={hero ? 640 : 480} height={hero ? 384 : 288} alt="" aria-hidden="true" decoding="async" loading={hero ? 'eager' : 'lazy'} fetchpriority={hero ? 'high' : undefined} />;
}
